return items.map(item => {
  const text = item.json.text || '';

  // Buscar en texto plano primero con el patrón Email:
  const emailLineMatch = text.match(/Email:\s*<?(?:mailto:)?([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})>?/i);
  if (emailLineMatch) {
    return { json: { ...item.json, extracted_email: emailLineMatch[1] } };
  }

  // Fallback: buscar en blocks de Slack el primer link después de "Email:"
  const blocks = item.json.blocks || [];
  let foundEmailLabel = false;
  let extracted_email = null;

  for (const block of blocks) {
    for (const section of (block.elements || [])) {
      for (const el of (section.elements || [])) {
        if (el.type === 'text' && el.text.includes('Email:')) {
          foundEmailLabel = true;
        }
        if (foundEmailLabel && el.type === 'link' && el.url?.startsWith('mailto:')) {
          extracted_email = el.url.replace('mailto:', '');
          break;
        }
      }
      if (extracted_email) break;
    }
    if (extracted_email) break;
  }

  return { json: { ...item.json, extracted_email } };
});

