const slackData = $('Mensaje en canal').item.json;
const hexData = $('Extract HEX data').item.json;
const text = slackData.text || '';

const emailMatch = text.match(/Email:\s*<?([^>\n|]+)>?/);
const email_usuario = emailMatch ? emailMatch[1].trim().replace(/[<>]/g,'') : hexData.email || '';

const asuntoMatch = text.match(/Asunto:\s*([^\n]+)/);
const asunto = asuntoMatch ? asuntoMatch[1].trim() : '';

const feedbackMatch = text.match(/Feedback:\s*([\s\S]+)$/);
const feedback_text = feedbackMatch ? feedbackMatch[1].trim() : '';

const username = slackData.username || '';
const numMatch = username.match(/#(\d+)/);
const numero_feedback = numMatch ? numMatch[1] : 'N/A';

return [{
  json: {
    email_usuario,
    asunto,
    feedback_text,
    numero_feedback,
    channel: hexData.channel || slackData.channel,
    thread_ts: hexData.thread_ts || slackData.ts,
    nivel: hexData.NIVEL,
    primer_ticket: hexData.FIRST_TICKET,
    entry_fees: hexData.ENTRY_FEES,
    net_revenue: hexData.NET_REVENUE,
    tickets: hexData.TICKETS,
    user_id: hexData.USER_ID,
    user_status: hexData.USER_STATUS,
    is_blocked: hexData.IS_BLOCKED,
    is_in_review: hexData.IS_IN_REVIEW,
    block_type: hexData.BLOCK_TYPE,
