const data = $('Preparar datos feedback').item.json;

// Sanitizar feedback_text para evitar caracteres que rompan JSON
data.feedback_text = (data.feedback_text || '')
  .replace(/\n/g, ' ')
  .replace(/\r/g, ' ')
  .replace(/\t/g, ' ')
  .replace(/"/g, "'");

const texto = data.feedback_text.toLowerCase();

// Helpers para strings que llegan como "NO"/"SI"/"true"/"false"
const isTrue = (val) => val === true || val === 'true' || val === 'SI' || val === 'si';
const isBlocked = isTrue(data.is_blocked);
const isInReview = isTrue(data.is_in_review);
const blockedComment = (data.blocked_comment || '').toLowerCase();

// ────────────────────────────────────────────
// GRUPO 1 — BLOQUEO (prioridad máxima)
// ────────────────────────────────────────────
if (isBlocked && blockedComment.includes('kyc')) {
  return [{ json: { ...data, tipo: 'BLOQUEO', subtipo: 'kyc' } }];
}
if (isBlocked) {
  return [{ json: { ...data, tipo: 'BLOQUEO', subtipo: 'blocked' } }];
}
if (isInReview) {
  return [{ json: { ...data, tipo: 'BLOQUEO', subtipo: 'in_review' } }];
}

// ────────────────────────────────────────────
// GRUPO 2 — ESCALAR_CX (identidad siempre)
// ────────────────────────────────────────────
const palabrasIdentidad = [
  'identidad', 'mi ine', 'subir ine', 'foto ine', 'pasaporte', 'identificacion',
  'verificación de identidad', 'verificacion de identidad',
  'validación de identidad', 'validacion de identidad',
  'verificar identidad', 'validar identidad', 'validar mi identidad',
  'validar mi cuenta', 'verificar mi cuenta', 'verificar la cuenta', 'validar la cuenta', 'verificar mi identidad',
  'subir mi ine', 'kyc', 'credencial'
];
if (palabrasIdentidad.some(p => texto.includes(p))) {
  return [{ json: { ...data, tipo: 'ESCALAR_CX', subtipo: 'identidad' } }];
}

// ────────────────────────────────────────────
// GRUPO 3 — MENCIONA_BLOQUEO
// (usuario menciona bloqueo pero NO está bloqueado en HEX)
// ────────────────────────────────────────────
const palabrasBloqueo = [
  'bloquearon', 'bloqueada', 'bloqueado', 'bloqueo',
  'bloquearon otra cuenta', 'bloquearon mi cuenta',
  'bloqueo de cuenta', 'bloqueo cuenta'
];
if (!isBlocked && !isInReview && palabrasBloqueo.some(p => texto.includes(p))) {
  return [{ json: { ...data, tipo: 'MENCIONA_BLOQUEO', subtipo: 'menciona_bloqueo' } }];
}

// ────────────────────────────────────────────
// GRUPO 4 — RESPUESTA_AUTOMATICA
// ────────────────────────────────────────────
return [{ json: { ...data, tipo: 'RESPUESTA_AUTOMATICA', subtipo: 'general' } }];

