const data = $input.item.json.data;

// Buscar mensaje del assistant
const assistantMessage = data.find(m => m.role === 'assistant');

// Si no respondió a tiempo
if (!assistantMessage) {
  const feedbackData = $('Clasificar Feedback').item.json;
  return [{
    json: {
      ...feedbackData,
      email_body: null,
      subtipo: 'timeout_openai',
      razon: 'OpenAI no respondió a tiempo'
    }
  }];
}

const raw = assistantMessage.content[0].text.value;

// Fix regex — quita apertura y cierre por separado
const clean = raw
  .replace(/^```json\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch(e) {
  parsed = {
    email_body: clean,
    razon: 'JSON malformado — usando texto directo'
  };
}

// Formatear email_body
let emailBody = parsed.email_body || null;
if (emailBody) {
  emailBody = emailBody
    .replace(/\\n/g, '\n')
    .replace(/\s*\|\|\|\s*/g, '<SPLIT>')
    .replace(/\n\n+/g, '<SPLIT>')
    .replace(/\. (¡|¿|[A-ZÁÉÍÓÚÑ])/g, '.<SPLIT>$1')
    .replace(/¡Vamos con todo/g, '<SPLIT>¡Vamos con todo')
    .split('<SPLIT>')
    .map(p => p.trim())
    .filter(p => p.length > 20)
    .join('<br><br>');
}

// Tomar tipo y subtipo del nodo Clasificar Feedback
const feedbackData = $('Clasificar Feedback').item.json;

return [{
  json: {
    ...feedbackData,
    email_body: emailBody,
    razon: parsed.razon || null
  }
}];

